#[cfg(test)] mod bounds_meter {
 use super::*;use crate::executor_allocation_meter as meter;
 #[test]fn maximum_table(){
  use std::os::unix::ffi::OsStringExt;
  let paths:Vec<_>=(0..MOUNTS).map(|i|{let mut p=format!("/disk{i:03}/").into_bytes();p.resize(PATH_BYTES,0xff);std::ffi::OsString::from_vec(p)}).collect();
  let pool=Budget::new(4*1024*1024,0);let denied=Budget::new(0,0);let _=pool.snapshot();let _=denied.snapshot();
  meter::start();let mut refused=Table::new(&denied).unwrap();assert_eq!(refused.push(&paths[0],1,0),Err(Error::Budget));drop(refused);assert_eq!(meter::peek().allocations,0);
  let mut table=Table::new(&pool).unwrap();for(i,path)in paths.iter().enumerate(){table.push(path,1000+i as u64,100).unwrap();}
  assert_eq!(table.push(&paths[0],9999,0),Err(Error::Limit));
  let result=table.finish(&pool).unwrap().unwrap();let counts=meter::peek();let held=pool.snapshot().used;let peak=pool.snapshot().peak;
  assert!(counts.live>=0&&counts.live as usize<=held);assert!(counts.peak as usize<=peak);assert_eq!(result.total,1127);
  drop(result);let end=meter::stop();assert_eq!(end.live,0);assert_eq!(pool.snapshot().used,0);
  eprintln!("BOUNDS_ALLOC table retained={} peak={} held={} fee_peak={} denied_allocations=0 final=0",counts.live,counts.peak,held,peak);
 }
 #[test]fn native_volume(){let pool=Budget::new(4*1024*1024,0);let _=pool.snapshot();let cancel=Cancellation::default();meter::start();let result=sample(&pool,&cancel).unwrap().expect("this native evidence host has a writable volume");let counts=meter::peek();let held=pool.snapshot().used;let peak=pool.snapshot().peak;assert!(counts.live>=0&&counts.live as usize<=held);assert!(counts.peak as usize<=peak);drop(result);let end=meter::stop();assert_eq!(end.live,0);assert_eq!(pool.snapshot().used,0);eprintln!("BOUNDS_ALLOC native retained={} peak={} held={} fee_peak={} final=0",counts.live,counts.peak,held,peak);}
}

