#[cfg(all(test,any(target_os="linux",target_os="macos",windows)))] mod review_meter {
 use super::*;use crate::executor_allocation_meter as m;
 #[test] fn sampler(){
  let warm=crate::resources::Budget::new(128*1024*1024,0);let _scope=crate::resources::Scope::enter(warm);
  {let mut source=SystemSource::new();let _=source.sample(true,&crate::tasks::Cancellation::default());drop(source.processes());}
  let pool=crate::resources::Budget::new(128*1024*1024,0);let _scope=crate::resources::Scope::enter(pool.clone());let fee=pool.lease(Kind::Monitor,RESERVED).unwrap();
  let cancel=crate::tasks::Cancellation::default();let _=std::thread::current();
  m::start();let mut source=SystemSource::new();let _=source.sample(true,&cancel);drop(source.processes());let c=m::peek();let held=pool.snapshot().used;let peak=pool.snapshot().peak;
  assert!(c.live>=0 && c.live as usize<=held,"live={} fee={held}",c.live);assert!(c.peak as usize<=peak);drop(source);drop(fee);let end=m::stop();assert_eq!(end.live,0);assert_eq!(pool.snapshot().used,0);
  eprintln!("REVIEW_ALLOC sampler live={} peak={} held={} fee_peak={} final=0",c.live,c.peak,held,peak);
 }
}
